"use client";

import { useEffect, useRef } from "react";

interface Line {
  x: number;
  y: number;
  length: number;
  angle: number;
  // Speed removed, lines are stationary
  initialHue: number; // Base hue for this line
}

export default function GlowingLines() {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let animationFrameId: number;
    let lines: Line[] = [];

    const resizeCanvas = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      initLines();
    };

    const initLines = () => {
      lines = [];
      const numLines = 6; // Fewer, more prominent lines
      for (let i = 0; i < numLines; i++) {
        lines.push(createLine());
      }
    };

    const createLine = (): Line => {
      const maxDimension = Math.max(canvas.width, canvas.height);

      return {
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        // Make lines long enough to span across the screen
        length: maxDimension * 1.5,
        angle: Math.random() * Math.PI * 2,
        initialHue: Math.random() * 360,
      };
    };

    const draw = (time: number) => {
      // Clear canvas
      ctx.fillStyle = "black";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Global wave speed factor
      const waveSpeed = 0.05;

      lines.forEach((line) => {
        // Calculate dynamic color based on time and initial value
        // This creates a "wave" effect where colors cycle
        const currentHue = (line.initialHue + time * waveSpeed) % 360;
        const color = `hsl(${currentHue}, 100%, 50%)`;

        // Draw line
        ctx.beginPath();
        const endX = line.x + Math.cos(line.angle) * line.length;
        const endY = line.y + Math.sin(line.angle) * line.length;

        ctx.moveTo(line.x, line.y);
        ctx.lineTo(endX, endY);

        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.lineCap = "round";

        // Glow effect
        ctx.shadowBlur = 15;
        ctx.shadowColor = color;

        ctx.stroke();
      });

      animationFrameId = requestAnimationFrame(draw);
    };

    window.addEventListener("resize", resizeCanvas);
    resizeCanvas();
    requestAnimationFrame(draw);

    return () => {
      window.removeEventListener("resize", resizeCanvas);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className="fixed inset-0 w-full h-full pointer-events-none"
      style={{ background: "black", zIndex: 0 }}
    />
  );
}
